  // canvas state.
  'clearSharedProviderSlots',
  'forwardGeocode',
  'reverseGeocode',
  'routeCapabilities',
  'fetchElevationPoints',
  'registerUrlTemplateRasterTileSource',
  'clearUrlTemplateRasterTileSource',
  // The traffic layer's cache counters: no contract member reports them yet;
  // the developer console reads them on the browser target.
  'trafficFlowCacheStatistics',
  // The live search-place surface (M31): the contract's `MapSdk::suggest` and
  // `MapSdk::search`, each with its optional ranking boundary, answered by
