  'calculateDistanceMatrix',
  // The live traffic calls (M31): the contract's
  // `MapSdk::fetch_traffic_incidents`/`fetch_traffic_flow`, answered by the
  // active provider's traffic traits. Native-only in the contract today;
  // these wasm aliases stay ahead of it.
  'fetchTrafficIncidents',
  'fetchTrafficFlow',
  // The live route and raster-tile calls (M13): the same registered provider
  // set answering a two-waypoint Directions route and one Tiles API raster
  // tile. The native provider surface is contract-only today; these stay
