/**
 * The named camera constructors (`fit_bounds`, `interpolate`) are UDL
 * constructors, so they carry no `interface_members` entry to compare
 * against; their parity is asserted from the raw sources: the contract
 * declares each `[Name=…]` constructor and the wasm exports publish the
 * mirroring static beside the camera's other members.
 * @param {string} contract_text The raw UDL source.
 * @param {string} wasm_exports_text The raw `exports.rs` source.
 */
function assert_named_camera_constructors_agree(
  contract_text,
  wasm_exports_text,
) {
  for (const named_constructor of NAMED_CAMERA_CONSTRUCTORS) {
    assert(
      contract_text.includes(`Name=${named_constructor.contract_name}`),
      `The UDL contract must declare the`
      + ` "${named_constructor.contract_name}" camera constructor.`,
    );
    assert(
      wasm_exports_text.includes(
        `js_name = ${named_constructor.wasm_export_name}`,
      ),
      `The wasm "MapCamera" class must mirror the contract's`
      + ` "${named_constructor.contract_name}" constructor as`
      + ` "${named_constructor.wasm_export_name}".`,
    );
  }
}

/**
 * @param {ParsedContract} contract
 * @param {WasmExports} wasm_exports
 */
function assert_free_helpers_agree(contract, wasm_exports) {
  assert_members_present(
    contract.namespace_members,
    FROZEN_FREE_HELPER_NAMES.map(contract_spelling_of),
    'The UDL contract namespace',
  );
  assert_members_present(
    wasm_exports.free_function_names,
    FROZEN_FREE_HELPER_NAMES,
    'The wasm free helper exports',
  );
  // A free-function export may mirror a namespace free function or one of
  // the `MapSdk` members the browser surface spells as a free call.
  const map_sdk_members = contract.interface_members.get(CONTRACT_MAP_SDK_INTERFACE_NAME) ?? [];
  for (const wasm_helper of wasm_exports.free_function_names) {
    assert(
      contract.namespace_members.includes(contract_spelling_of(wasm_helper))
      || map_sdk_members.includes(contract_spelling_of(wasm_helper))
      || WASM_ONLY_FREE_HELPER_NAMES.includes(wasm_helper),
      `The wasm surface invents the free helper "${wasm_helper}", which the UDL contract lacks.`,
    );
  }
}

/** The UDL interface whose members the browser surface must serve. */
const CONTRACT_MAP_SDK_INTERFACE_NAME = 'MapSdk';

/**
 * Contract members the browser surface serves under a name its own casing rule
 * does not produce: the search calls read as the demo's `…Places` rows.
 */
const WASM_CONTRACT_MEMBER_SPELLINGS = new Map([
  ['suggest', ['suggestPlaces']],
  ['search', ['searchPlaces']],
]);

/**
 * Contract members the browser surface deliberately lacks, with the reason.
 * Each one is native-only by construction: a foreign callback trait cannot
 * cross the `wasm-bindgen` boundary, a browser page has no disk-backed tile
 * cache, and the failure diagnostics read back calls that only those foreign
 * adapters produce.
 */
const WASM_CONTRACT_MEMBER_EXCEPTIONS = new Map([
  ['register_geocoding_provider_from_foreign', 'a foreign callback trait cannot cross wasm-bindgen; a page registers through `configureProvider`'],
  ['register_raster_tile_provider_from_foreign', 'a foreign callback trait cannot cross wasm-bindgen; a page registers through `configureProvider` or the URL-template source'],
  ['register_vector_tile_provider_from_foreign', 'a foreign callback trait cannot cross wasm-bindgen; a page registers through `configureProvider`'],
  ['vector_tile_provider_is_registered', 'the browser readiness is reported by `providerRegistrations`, which lists every contract\'s registered state'],
  ['register_routing_provider_from_foreign', 'a foreign callback trait cannot cross wasm-bindgen; a page registers through `configureProvider`'],
  ['register_distance_matrix_provider_from_foreign', 'a foreign callback trait cannot cross wasm-bindgen; a page registers through `configureProvider`'],
  ['register_search_place_provider_from_foreign', 'a foreign callback trait cannot cross wasm-bindgen; a page registers through `configureProvider`'],
  ['register_traffic_incident_provider_from_foreign', 'a foreign callback trait cannot cross wasm-bindgen; a page registers through `configureProvider`'],
  ['register_traffic_flow_provider_from_foreign', 'a foreign callback trait cannot cross wasm-bindgen; a page registers through `configureProvider`'],
  ['register_elevation_provider_from_foreign', 'a foreign callback trait cannot cross wasm-bindgen; a page registers through `configureProvider`'],
  ['set_provider_credential_with_tile_cache', 'the browser has no disk-backed tile cache to install'],
  ['set_raster_tile_cache_time_to_live', 'the browser has no disk-backed tile cache to tune'],
  ['raster_tile_cache_terms', 'the browser has no disk-backed tile cache to report'],
  ['tile_cache_statistics', 'the browser has no disk-backed tile cache to report; the canvas status reports the vector payload cache hit and miss counters'],
  ['latest_provider_failure_diagnostics', 'the readback describes the foreign-provider adapters, which the browser has none of'],
]);

/**
 * Every `MapSdk` member the UDL declares must have a browser counterpart: the
 * free-function export its name spells, or an entry in
 * [`WASM_CONTRACT_MEMBER_EXCEPTIONS`]. This is the gate that keeps the
 * hand-maintained façade from silently falling behind the frozen contract
 * again.
 * @param {ParsedContract} contract
 * @param {WasmExports} wasm_exports
 */
function assert_map_sdk_members_have_wasm_counterparts(contract, wasm_exports) {
  const map_sdk_members = contract.interface_members.get(CONTRACT_MAP_SDK_INTERFACE_NAME);
  assert(
    map_sdk_members !== undefined && map_sdk_members.length > 0,
    'The UDL contract declares the MapSdk interface.',
  );
  for (const contract_member of map_sdk_members) {
    const candidate_names = WASM_CONTRACT_MEMBER_SPELLINGS.get(contract_member)
      ?? [contractFieldNameToTypescript(contract_member)];
    const is_served = candidate_names.some((candidate_name) =>
      wasm_exports.free_function_names.includes(candidate_name));
    if (is_served) {
      continue;
    }
    assert(
      WASM_CONTRACT_MEMBER_EXCEPTIONS.has(contract_member),
      `The UDL contract's MapSdk member "${contract_member}" has no wasm export`
      + ` (\`${candidate_names.join('` or `')}\`) and is not a listed exception.`,
    );
  }
  for (const exception_member of WASM_CONTRACT_MEMBER_EXCEPTIONS.keys()) {
    assert(
      map_sdk_members.includes(exception_member),
      `The wasm exception list names "${exception_member}", which the UDL`
      + ` contract's MapSdk no longer declares; drop the stale entry.`,
    );
  }
}

/**
 * @param {ParsedContract} contract
 * @param {WasmExports} generated_exports
 */
function assert_generated_exports_agree(contract, generated_exports) {
  const contract_methods = contract.interface_members.get(CONTRACT_CAMERA_INTERFACE_NAME);
  assert(contract_methods !== undefined, 'The UDL contract declares the camera interface.');
  assert_members_present(
    generated_exports.camera_method_names,
    FROZEN_CAMERA_METHOD_NAMES,
    'The generated pkg "MapCamera" class',
  );
  assert_members_present(
    generated_exports.free_function_names,
    FROZEN_FREE_HELPER_NAMES,
    'The generated pkg free helper functions',
  );
  for (const generated_method of generated_exports.camera_method_names) {
    if (generated_method === GENERATED_CONSTRUCTOR_METHOD_NAME
      || generated_method === WASM_CONSTRUCTOR_METHOD_NAME) {
      continue;
    }
    assert(
      contract_methods.includes(contract_spelling_of(generated_method)),
      `The generated pkg "MapCamera" class invents the member "${generated_method}".`,
    );
  }
  const generated_map_sdk_members =
    contract.interface_members.get(CONTRACT_MAP_SDK_INTERFACE_NAME) ?? [];
  for (const generated_helper of generated_exports.free_function_names) {
    assert(
      contract.namespace_members.includes(contract_spelling_of(generated_helper))
      || generated_map_sdk_members.includes(contract_spelling_of(generated_helper))
      || WASM_ONLY_FREE_HELPER_NAMES.includes(generated_helper),
      `The generated pkg invents the free helper "${generated_helper}".`,
    );
  }
  const route_simulator_methods = contract.interface_members.get(
    CONTRACT_ROUTE_SIMULATOR_INTERFACE_NAME,
  );
  assert(
    route_simulator_methods !== undefined,
    'The UDL contract declares the RouteSimulator interface.',
  );
  assert_members_present(
    generated_exports.route_simulator_method_names,
    FROZEN_ROUTE_SIMULATOR_METHOD_NAMES,
    'The generated pkg "RouteSimulator" class',
  );
  for (const generated_method of generated_exports.route_simulator_method_names) {
    if (generated_method === GENERATED_CONSTRUCTOR_METHOD_NAME
      || generated_method === WASM_CONSTRUCTOR_METHOD_NAME) {
      continue;
    }
    assert(
      route_simulator_methods.includes(contract_spelling_of(generated_method)),
      `The generated pkg "RouteSimulator" class invents the member`
      + ` "${generated_method}".`,
    );
  }
  const navigator_methods = contract.interface_members.get(
    CONTRACT_NAVIGATOR_INTERFACE_NAME,
  );
  assert(
    navigator_methods !== undefined,
    'The UDL contract declares the Navigator interface.',
  );
  assert_members_present(
    generated_exports.navigator_method_names,
    FROZEN_NAVIGATOR_METHOD_NAMES,
    'The generated pkg "Navigator" class',
  );
  for (const generated_method of generated_exports.navigator_method_names) {
    if (generated_method === GENERATED_CONSTRUCTOR_METHOD_NAME
      || generated_method === WASM_CONSTRUCTOR_METHOD_NAME) {
      continue;
    }
    assert(
      navigator_methods.includes(contract_spelling_of(generated_method))
      || WASM_ONLY_NAVIGATOR_METHOD_NAMES.includes(generated_method),
      `The generated pkg "Navigator" class invents the member`
      + ` "${generated_method}".`,
    );
  }
}

/**
 * Runs every contract-sync comparison; throws on the first drift. Shared by
 * the `node --test` registration and the Playwright `globalSetup`.
 */
function run_contract_sync_checks() {
  // The contract mirror is generated: a one-line drift in the committed
  // façade fails here before any callable surface is compared.
  const facade_check = checkWebFacade();
  assert(
    !facade_check.isStale,
    'The generated WebAssembly façade has drifted from the UniFFI contract: '
    + `${facade_check.staleFiles.map((stale_file) => stale_file.relativePath).join(', ')}. `
    + 'Run `node scripts/generate-web-facade.mjs` and commit the result.',
  );

  const contract = parseUniffiContract(readFileSync(UNIFFI_CONTRACT_PATH, 'utf8'));
  const wasm_exports = parse_wasm_exports(
    readFileSync(WASM_EXPORTS_PATH, 'utf8'),
    readFileSync(WASM_NAVIGATION_EXPORTS_PATH, 'utf8'),
    readFileSync(WASM_CANVAS_EXPORTS_PATH, 'utf8'),
    readFileSync(WASM_LIVE_PROVIDERS_PATH, 'utf8'),
    readFileSync(WASM_DIAGNOSTICS_PATH, 'utf8'),
  );

  assert_camera_methods_agree(contract, wasm_exports);
  assert_route_simulator_methods_agree(contract, wasm_exports);
  assert_navigator_methods_agree(contract, wasm_exports);
  assert_map_view_methods_agree(contract, wasm_exports);
  assert_named_camera_constructors_agree(
    readFileSync(UNIFFI_CONTRACT_PATH, 'utf8'),
    readFileSync(WASM_EXPORTS_PATH, 'utf8'),
  );
  assert_free_helpers_agree(contract, wasm_exports);
  assert_map_sdk_members_have_wasm_counterparts(contract, wasm_exports);
  // The generated pkg declarations are a build artifact and may be absent on
  // a fresh checkout; the parity is then already covered through exports.rs.
  let generated_exports = null;
  try {
    generated_exports = parse_generated_wasm_typescript(
      readFileSync(GENERATED_TYPESCRIPT_PATH, 'utf8'),
    );
  } catch (generated_is_absent) {
    generated_exports = null;
  }
  if (generated_exports !== null) {
    assert_generated_exports_agree(contract, generated_exports);
  }
}

export {
  contractFieldNameToTypescript,
  parseUniffiContract,
  run_contract_sync_checks,
};

/** The `node --test` suite name of the parity assertions. */
const CONTRACT_SYNC_TEST_NAME =
  'the wasm TypeScript surface mirrors the frozen UniFFI contract';

// Run the suite only when this file is the entry point; the Playwright
// `globalSetup` imports the exported runner instead.
const RUNNING_AS_ENTRY = process.argv[1] !== undefined
  && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url;

if (RUNNING_AS_ENTRY) {
  test(CONTRACT_SYNC_TEST_NAME, () => {
    run_contract_sync_checks();
  });
}